<!doctype html>
<html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Bài 2 - Đặt vé xem phim</title><script src="https://unpkg.com/vue@3/dist/vue.global.js"></script><style>
*{box-sizing:border-box}body{margin:0;background:#f1f5f9;font-family:Arial,sans-serif;color:#172033}.page{max-width:850px;margin:40px auto;padding:0 16px}.card{background:#fff;border-radius:16px;padding:28px;box-shadow:0 8px 25px #0f172a18}.form{display:grid;grid-template-columns:1fr 1fr;gap:18px}.field{display:grid;gap:7px}.full{grid-column:1/-1}label,legend{font-weight:bold}input,select{font:inherit;padding:11px;border:1px solid #cbd5e1;border-radius:8px;width:100%}.options{display:flex;gap:18px;flex-wrap:wrap}.option{font-weight:normal;display:flex;gap:6px;align-items:center}.option input{width:auto}.quantity{display:flex;gap:8px}.quantity button{width:42px}.quantity input{text-align:center}.total{margin:20px 0;padding:18px;background:#eff6ff;border-radius:10px;display:flex;justify-content:space-between}.total strong{font-size:22px;color:#1d4ed8}button{border:0;border-radius:8px;padding:10px 15px;background:#2563eb;color:white;font-weight:bold;cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}.secondary{background:#dbeafe;color:#1d4ed8}.success{margin-top:18px;padding:15px;background:#dcfce7;color:#166534;border-radius:9px}@media(max-width:650px){.form{grid-template-columns:1fr}.full{grid-column:auto}}
</style></head><body><main class="page" id="app"><section class="card"><h1>Đặt vé xem phim</h1><form @submit.prevent="submitBooking"><div class="form">
<div class="field"><label>Họ tên khách hàng</label><input v-model.trim="customer" type="text" placeholder="Nguyễn Văn A"></div>
<div class="field"><label>Suất chiếu</label><select v-model="showtime"><option v-for="time in showtimes" :key="time">{{time}}</option></select></div>
<fieldset class="field"><legend>Loại vé</legend><div class="options"><label class="option"><input v-model="ticketType" type="radio" value="normal">Vé thường: 70.000 đồng</label><label class="option"><input v-model="ticketType" type="radio" value="vip">Vé VIP: 100.000 đồng</label></div></fieldset>
<div class="field"><label>Số lượng vé (1-10)</label><div class="quantity"><button class="secondary" type="button" @click="decrease">−</button><input v-model.number="quantity" type="number" min="1" max="10" step="1"><button class="secondary" type="button" @click="increase">+</button></div></div>
<label class="option full"><input v-model="combo" type="checkbox">Chọn combo bắp nước: 45.000 đồng</label></div>
<div class="total"><span>Tổng tiền</span><strong>{{money(total)}}</strong></div><button type="submit" :disabled="!canSubmit">Đặt vé</button></form><div class="success" v-if="message">{{message}}</div></section></main><script>
const {createApp}=Vue;createApp({data(){return{customer:'',showtimes:['09:00 - 11:00','14:30 - 16:30','19:00 - 21:00'],showtime:'09:00 - 11:00',ticketType:'normal',quantity:1,combo:false,message:''}},computed:{price(){return this.ticketType==='vip'?100000:70000},validQuantity(){return Number.isInteger(this.quantity)&&this.quantity>=1&&this.quantity<=10},total(){return this.price*this.quantity+(this.combo?45000:0)},canSubmit(){return this.customer.length>0&&this.validQuantity}},methods:{money(v){return new Intl.NumberFormat('vi-VN').format(v)+' đồng'},increase(){if(this.quantity<10)this.quantity++},decrease(){if(this.quantity>1)this.quantity--},submitBooking(){if(this.canSubmit)this.message=`Đặt vé thành công! ${this.customer} đã đặt ${this.quantity} vé ${this.ticketType==='vip'?'VIP':'thường'} cho suất ${this.showtime}. Tổng tiền: ${this.money(this.total)}.`}}}).mount('#app');
</script></body></html>
